parameters.jsCode:
const globalStaticData = $getWorkflowStaticData('global');

console.log('Global Static Data:',globalStaticData);
const chatMode = $input.first()?.json?.botCommand || globalStaticData.chatMode || 'risk_assessment_chat'
globalStaticData.chatMode = chatMode
console.log('Global Static Data After Setting:', globalStaticData)
return [
  {
     chatMode
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
 const severityMap = new Map();
const mergedIssues = item.json.mergedIssues.flatMap(issue => issue.output?.issues || []);

for (const issue of mergedIssues) {
  severityMap.set(issue?.severity, (severityMap.get(issue?.severity) || 0) + 1);
}

const severityEnum = { Critical: 6, Major: 5 };
const riskEnum = { High: "High", Medium: "Medium", Low: "Low" };

const criticalCount = severityMap.get(severityEnum.Critical) || 0;
const majorCount = severityMap.get(severityEnum.Major) || 0;

const riskAssessment = criticalCount > 1 ? riskEnum.High : majorCount > 1 ? riskEnum.Medium : riskEnum.Low;

item.json.finalAssessment = { riskAssessment, issues: mergedIssues }
item.json.mergedIssues = {}
}


return $input.all();

